let inputString = "";
let currentLine = 0;
process.stdin.on("data", (data) => {
  inputString += data;
});
process.stdin.on("end", function () {
  inputString = inputString
    .trim()
    .split("\n")
    .map((str) => str.trim());
  main();
});
function readLine() {
  return inputString[currentLine++];
}
function main() {
  const [total, front, back] = readLine()
    .split(" ")
    .map((n) => parseInt(n));
  const diff = total - front;

  if (diff > back) console.log(back + 1);
  else console.log(diff);
}
